import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { supabase } from '../../supabase';
import { Plus, Edit2, Trash2, X, Upload, Image as ImageIcon, RefreshCw } from 'lucide-react';
import { Project } from '../Projects';
import { documentProjects } from '../../data/portfolioData';

export default function AdminProjects() {
  const { isAdmin, loading } = useAuth();
  const [projects, setProjects] = useState<Project[]>([]);
  const [fetching, setFetching] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);

  // File Upload State
  const [uploadingImage, setUploadingImage] = useState(false);
  const [uploadingGallery, setUploadingGallery] = useState(false);
  const [isFetchingInfo, setIsFetchingInfo] = useState(false);
  const mainImageInputRef = useRef<HTMLInputElement>(null);
  const galleryInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const [formData, setFormData] = useState({
    title: '', category: '상업', subcategory: '', year: new Date().getFullYear().toString(),
    location: '', client: '', role: '', image: '', gallery: '',
    description: '', challenge: '', solution: '',
    zoning: '', land_area: '', building_area: '', total_floor_area: '',
    scale: '', far: '', bcr: '', notes: ''
  });

  const fetchProjects = async () => {
    const { data, error } = await supabase
      .from('projects')
      .select('*')
      .neq('category', '인테리어')
      .order('created_at', { ascending: false });
      
    if (error) {
      console.error("Error fetching projects:", error);
    } else {
      setProjects(data as Project[]);
    }
    setFetching(false);
  };

  useEffect(() => {
    if (!isAdmin) return;

    fetchProjects();

    // Set up real-time subscription
    const channel = supabase
      .channel('projects_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'projects' }, () => {
        fetchProjects();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [isAdmin]);

  const handleOpenModal = (project?: Project) => {
    if (project) {
      setEditingProject(project);
      setFormData({
        title: project.title,
        category: project.category,
        subcategory: project.subcategory || '',
        year: project.year || '',
        location: project.location || '',
        client: project.client || '',
        role: project.role || '',
        image: project.image || '',
        gallery: project.gallery?.join('\n') || '',
        description: project.description || '',
        challenge: project.challenge || '',
        solution: project.solution || '',
        zoning: project.zoning || '',
        land_area: project.land_area || '',
        building_area: project.building_area || '',
        total_floor_area: project.total_floor_area || '',
        scale: project.scale || '',
        far: project.far || '',
        bcr: project.bcr || '',
        notes: project.notes || ''
      });
    } else {
      setEditingProject(null);
      setFormData({
        title: '', category: '상업', subcategory: '', year: new Date().getFullYear().toString(),
        location: '', client: '', role: '', image: '', gallery: '',
        description: '', challenge: '', solution: '',
        zoning: '', land_area: '', building_area: '', total_floor_area: '',
        scale: '', far: '', bcr: '', notes: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleMainImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingImage(true);
    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}.${fileExt}`;
      const filePath = `main/${fileName}`;

      const { error: uploadError } = await supabase.storage
        .from('projects')
        .upload(filePath, file, { cacheControl: '31536000', upsert: false });

      if (uploadError) throw uploadError;

      const { data } = supabase.storage.from('projects').getPublicUrl(filePath);
      
      setFormData(prev => ({ ...prev, image: data.publicUrl }));
    } catch (error) {
      console.error("Upload error:", error);
      alert("이미지 업로드에 실패했습니다.");
    } finally {
      setUploadingImage(false);
    }
  };

  const handleGalleryUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0) return;

    setUploadingGallery(true);
    const newUrls: string[] = [];

    try {
      for (const file of files) {
        const fileExt = file.name.split('.').pop();
        const fileName = `${Date.now()}_${Math.random().toString(36).substring(7)}.${fileExt}`;
        const filePath = `gallery/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from('projects')
          .upload(filePath, file, { cacheControl: '31536000', upsert: false });

        if (uploadError) throw uploadError;

        const { data } = supabase.storage.from('projects').getPublicUrl(filePath);
        newUrls.push(data.publicUrl);
      }
      
      setFormData(prev => {
        const currentGallery = prev.gallery ? prev.gallery.split('\n').filter(url => url.trim() !== '') : [];
        return {
          ...prev,
          gallery: [...currentGallery, ...newUrls].join('\n')
        };
      });
    } catch (error) {
      console.error("Gallery upload error:", error);
      alert("갤러리 이미지 업로드에 실패했습니다.");
    } finally {
      setUploadingGallery(false);
      if (galleryInputRef.current) galleryInputRef.current.value = '';
    }
  };

  const handleFetchPropertyInfo = async () => {
    if (!formData.location) {
      alert("지역(위치)에 주소를 먼저 입력해주세요. (예: 경기도 용인시 수지구 풍덕천동 977)");
      return;
    }

    setIsFetchingInfo(true);
    const vworldKey = '25317F3E-9FD7-3AC3-AEB5-8120BAC49500';
    const domain = window.location.hostname;

    try {
      // 1. 주소 검색 (Vworld Search API)
      let searchUrl = `https://api.vworld.kr/req/search?service=search&request=search&version=2.0&crs=EPSG:4326&size=1&page=1&query=${encodeURIComponent(formData.location)}&type=address&category=parcel&format=json&errorformat=json&key=${vworldKey}`;
      
      let searchRes = await fetch(searchUrl);
      let searchData = await searchRes.json();

      // 지번 검색 실패 시 도로명 검색 시도
      if (searchData.response?.status !== 'OK') {
        searchUrl = `https://api.vworld.kr/req/search?service=search&request=search&version=2.0&crs=EPSG:4326&size=1&page=1&query=${encodeURIComponent(formData.location)}&type=address&category=road&format=json&errorformat=json&key=${vworldKey}`;
        searchRes = await fetch(searchUrl);
        searchData = await searchRes.json();
      }

      if (searchData.response?.status !== 'OK') {
        alert("주소를 찾을 수 없습니다. 정확한 지번 또는 도로명 주소를 입력해주세요.");
        setIsFetchingInfo(false);
        return;
      }

      const item = searchData.response.result.items[0];
      const x = item.point.x;
      const y = item.point.y;

      // 2. 지적도 정보 조회 (면적, 지목) - LP_PA_CBND_BUBUN
      const cadastralUrl = `https://api.vworld.kr/req/data?service=data&request=GetFeature&data=LP_PA_CBND_BUBUN&key=${vworldKey}&domain=${domain}&geomFilter=POINT(${x} ${y})&format=json`;
      const cadastralRes = await fetch(cadastralUrl);
      const cadastralData = await cadastralRes.json();

      let landArea = '';
      let jimok = '';

      if (cadastralData.response?.status === 'OK' && cadastralData.response.result?.featureCollection?.features?.length > 0) {
        const feature = cadastralData.response.result.featureCollection.features[0];
        landArea = feature.properties.area || '';
        jimok = feature.properties.jimok || '';
      }

      // 3. 용도지역 정보 조회 - LT_C_UQ111
      const zoningUrl = `https://api.vworld.kr/req/data?service=data&request=GetFeature&data=LT_C_UQ111&key=${vworldKey}&domain=${domain}&geomFilter=POINT(${x} ${y})&format=json`;
      const zoningRes = await fetch(zoningUrl);
      const zoningData = await zoningRes.json();

      let zoningName = '';
      if (zoningData.response?.status === 'OK' && zoningData.response.result?.featureCollection?.features?.length > 0) {
        const feature = zoningData.response.result.featureCollection.features[0];
        zoningName = feature.properties.mnm || '';
      }

      // Update form data
      setFormData(prev => ({
        ...prev,
        land_area: landArea ? `${landArea}` : prev.land_area,
        zoning: zoningName ? `${zoningName} ${jimok ? `(지목: ${jimok})` : ''}` : prev.zoning,
      }));

      alert(`정보를 성공적으로 불러왔습니다!\n면적: ${landArea}㎡\n용도지역: ${zoningName}\n지목: ${jimok}`);

    } catch (error) {
      console.error("Vworld API Error:", error);
      alert("정보를 불러오는 중 오류가 발생했습니다. 브이월드 API 도메인 설정이나 일일 호출 한도를 확인해주세요.");
    } finally {
      setIsFetchingInfo(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    
    const projectData = {
      title: formData.title,
      category: formData.category,
      subcategory: formData.subcategory,
      year: formData.year,
      location: formData.location,
      client: formData.client,
      role: formData.role,
      image: formData.image,
      gallery: formData.gallery.split('\n').filter(url => url.trim() !== ''),
      description: formData.description,
      challenge: formData.challenge,
      solution: formData.solution,
      zoning: formData.zoning,
      land_area: formData.land_area,
      building_area: formData.building_area,
      total_floor_area: formData.total_floor_area,
      scale: formData.scale,
      far: formData.far,
      bcr: formData.bcr,
      notes: formData.notes
    };

    try {
      if (editingProject) {
        const { error } = await supabase
          .from('projects')
          .update(projectData)
          .eq('id', editingProject.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('projects')
          .insert([projectData]);
        if (error) throw error;
      }
      await fetchProjects();
      setIsModalOpen(false);
    } catch (error) {
      console.error("Error saving project:", error);
      alert("저장에 실패했습니다.");
    }
  };

  const handleDelete = async (id: string) => {
    if (window.confirm("정말로 이 프로젝트를 삭제하시겠습니까?")) {
      try {
        const { error } = await supabase
          .from('projects')
          .delete()
          .eq('id', id);
        if (error) throw error;
        await fetchProjects();
      } catch (error) {
        console.error("Error deleting project:", error);
        alert("삭제에 실패했습니다.");
      }
    }
  };

  const [syncing, setSyncing] = useState(false);
  const handleSyncDocumentProjects = async () => {
    setSyncing(true);
    try {
      let added = 0;
      for (const doc of documentProjects) {
        const exists = projects.some(p => p.title.trim() === doc.title.trim());
        if (!exists) {
          const { error } = await supabase.from('projects').insert([{
            title: doc.title,
            category: doc.category,
            subcategory: doc.subcategory,
            year: doc.year,
            location: doc.location,
            client: doc.client,
            role: doc.role,
            image: doc.image,
            gallery: doc.gallery,
            description: doc.description,
            challenge: doc.challenge,
            solution: doc.solution,
            zoning: doc.zoning,
            land_area: doc.land_area,
            building_area: doc.building_area,
            total_floor_area: doc.total_floor_area,
            scale: doc.scale,
            far: doc.far,
            bcr: doc.bcr,
            notes: doc.notes
          }]);
          if (!error) added++;
        }
      }
      await fetchProjects();
      alert(`문서 포트폴리오 동기화 완료: ${added}건 신규 등록되었습니다.`);
    } catch (err) {
      console.error("Sync error:", err);
      alert("동기화 중 오류가 발생했습니다.");
    } finally {
      setSyncing(false);
    }
  };

  if (loading || fetching) return <div className="p-4 md:p-8">Loading...</div>;
  if (!isAdmin) return <div className="p-4 md:p-8">접근 권한이 없습니다.</div>;

  return (
    <div className="p-4 md:p-8 w-full">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6 md:mb-8">
        <h1 className="text-2xl md:text-3xl font-bold">포트폴리오 관리</h1>
        <div className="flex flex-wrap gap-3 w-full sm:w-auto">
          <button
            onClick={handleSyncDocumentProjects}
            disabled={syncing}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors disabled:opacity-50 text-sm font-medium"
          >
            <RefreshCw size={18} className={syncing ? 'animate-spin' : ''} />
            {syncing ? '동기화 중...' : '문서 포트폴리오(5건) DB 동기화'}
          </button>
          <button 
            onClick={() => handleOpenModal()}
            className="bg-black text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-800 w-full sm:w-auto justify-center text-sm font-medium"
          >
            <Plus size={20} /> 새 프로젝트 추가
          </button>
        </div>
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {projects.map((project) => (
          <div key={project.id} className="bg-white rounded-xl shadow overflow-hidden border border-gray-100">
            <div className="h-48 overflow-hidden relative">
              <img src={project.image} alt={project.title} className="w-full h-full object-cover" />
              <div className="absolute top-2 right-2 flex gap-2">
                <button onClick={() => handleOpenModal(project)} className="p-2 bg-white/90 rounded-full shadow hover:bg-white text-gray-700">
                  <Edit2 size={16} />
                </button>
                <button onClick={() => handleDelete(project.id)} className="p-2 bg-white/90 rounded-full shadow hover:bg-white text-red-600">
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
            <div className="p-4">
              <div className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-1">{project.category}</div>
              <h3 className="text-lg font-bold text-gray-900 mb-2 truncate">{project.title}</h3>
              <p className="text-sm text-gray-600 line-clamp-2">{project.description || '설명 없음'}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[90vh] flex flex-col overflow-hidden">
            <div className="flex justify-between items-center p-6 border-b border-gray-100 flex-shrink-0">
              <h2 className="text-2xl font-bold">{editingProject ? '프로젝트 수정' : '새 프로젝트 추가'}</h2>
              <button onClick={() => setIsModalOpen(false)} className="text-gray-500 hover:text-gray-900">
                <X size={24} />
              </button>
            </div>
            
            <form onSubmit={handleSubmit} className="p-6 overflow-y-auto space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">프로젝트명 *</label>
                  <input required type="text" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">카테고리 (대분류) *</label>
                  <select value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black">
                    <option value="상업">상업</option>
                    <option value="주거">주거</option>
                    <option value="복합개발">복합개발</option>
                    <option value="근생">근생</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">중분류</label>
                  <input type="text" value={formData.subcategory} onChange={e => setFormData({...formData, subcategory: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">연도 *</label>
                  <input required type="text" value={formData.year} onChange={e => setFormData({...formData, year: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">지역 (위치)</label>
                  <div className="flex gap-2">
                    <input type="text" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} placeholder="예: 경기도 용인시 수지구 풍덕천동 977" className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                    <button 
                      type="button" 
                      onClick={handleFetchPropertyInfo}
                      disabled={isFetchingInfo}
                      className="bg-indigo-600 text-white px-3 py-2 rounded-lg text-sm hover:bg-indigo-700 whitespace-nowrap disabled:bg-indigo-400 transition-colors"
                    >
                      {isFetchingInfo ? '불러오는 중...' : '정보 자동입력'}
                    </button>
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">용도관련 원문 (Zoning)</label>
                  <input type="text" value={formData.zoning} onChange={e => setFormData({...formData, zoning: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">대지면적 (㎡)</label>
                  <input type="text" value={formData.land_area} onChange={e => setFormData({...formData, land_area: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">건축면적 (㎡)</label>
                  <input type="text" value={formData.building_area} onChange={e => setFormData({...formData, building_area: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">연면적 (㎡)</label>
                  <input type="text" value={formData.total_floor_area} onChange={e => setFormData({...formData, total_floor_area: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">규모</label>
                  <input type="text" value={formData.scale} onChange={e => setFormData({...formData, scale: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">용적률 (%)</label>
                  <input type="text" value={formData.far} onChange={e => setFormData({...formData, far: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">건폐율 (%)</label>
                  <input type="text" value={formData.bcr} onChange={e => setFormData({...formData, bcr: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">클라이언트</label>
                  <input type="text" value={formData.client} onChange={e => setFormData({...formData, client: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">역할 (Role)</label>
                  <input type="text" value={formData.role} onChange={e => setFormData({...formData, role: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-1">비고</label>
                  <input type="text" value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">메인 이미지 *</label>
                <div className="flex gap-4 items-start">
                  <div className="flex-1">
                    <input required type="url" value={formData.image} onChange={e => setFormData({...formData, image: e.target.value})} placeholder="https://..." className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black mb-2" />
                    <input 
                      type="file" 
                      accept="image/*" 
                      className="hidden" 
                      ref={mainImageInputRef}
                      onChange={handleMainImageUpload}
                    />
                    <button 
                      type="button"
                      onClick={() => mainImageInputRef.current?.click()}
                      disabled={uploadingImage}
                      className="flex items-center gap-2 text-sm text-gray-600 bg-gray-100 hover:bg-gray-200 px-4 py-2 rounded-lg transition-colors"
                    >
                      {uploadingImage ? '업로드 중...' : <><Upload size={16} /> 파일 업로드</>}
                    </button>
                  </div>
                  {formData.image && (
                    <div className="w-24 h-24 rounded-lg overflow-hidden border border-gray-200 flex-shrink-0">
                      <img src={formData.image} alt="Preview" className="w-full h-full object-cover" />
                    </div>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">갤러리 이미지 (선택)</label>
                <div className="space-y-2">
                  <textarea value={formData.gallery} onChange={e => setFormData({...formData, gallery: e.target.value})} rows={3} placeholder="https://...&#10;https://..." className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                  <input 
                    type="file" 
                    accept="image/*" 
                    multiple
                    className="hidden" 
                    ref={galleryInputRef}
                    onChange={handleGalleryUpload}
                  />
                  <button 
                    type="button"
                    onClick={() => galleryInputRef.current?.click()}
                    disabled={uploadingGallery}
                    className="flex items-center gap-2 text-sm text-gray-600 bg-gray-100 hover:bg-gray-200 px-4 py-2 rounded-lg transition-colors"
                  >
                    {uploadingGallery ? '업로드 중...' : <><ImageIcon size={16} /> 여러 파일 업로드</>}
                  </button>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">프로젝트 개요</label>
                <textarea value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} rows={4} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">문제점 (Challenge)</label>
                  <textarea value={formData.challenge} onChange={e => setFormData({...formData, challenge: e.target.value})} rows={4} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">해결책 (Solution)</label>
                  <textarea value={formData.solution} onChange={e => setFormData({...formData, solution: e.target.value})} rows={4} className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-black" />
                </div>
              </div>

              <div className="flex justify-end gap-4 pt-4 border-t border-gray-100">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50">취소</button>
                <button type="submit" className="px-6 py-2 bg-black text-white rounded-lg hover:bg-gray-800">저장하기</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
